beforeSaveCustomScript:
if (typ == 'U') {
    color = '#00994d';
    calendarTitle = string\concatenate(name, ' - Urlaub');
} else if (typ == 'K') {
    color = '#e6b94b';
    calendarTitle = string\concatenate(name, ' - Krankheit');
} else if (typ == 'unbezahlterUrlaub') {
    color = '#e07800';
    calendarTitle = string\concatenate(name, ' - Unbez. Urlaub');
} else if (typ == 'freizeitausgleich') {
    color = '#5bc0de';
    calendarTitle = string\concatenate(name, ' - Freizeitausgleich');
} else {
    calendarTitle = name;
}
